"""Simple prep & inventory tracker for small restaurants (prototype)."""
import json, os, sys
from datetime import date

DATA = "inventory.json"

def load():
    if os.path.exists(DATA):
        with open(DATA) as f:
            return json.load(f)
    return {"items": {}, "log": []}

def save(d):
    with open(DATA, "w") as f:
        json.dump(d, f, indent=2)

def add(name, qty, par):
    d = load()
    d["items"][name] = {"qty": float(qty), "par": float(par)}
    save(d)

def use(name, qty):
    d = load()
    item = d["items"][name]
    item["qty"] -= float(qty)
    d["log"].append({"date": date.today().isoformat(), "item": name, "used": float(qty)})
    save(d)

def reorder_list():
    d = load()
    return [(n, i["par"] - i["qty"]) for n, i in d["items"].items() if i["qty"] < i["par"]]

if __name__ == "__main__":
    cmd = sys.argv[1:]
    if cmd[:1] == ["add"]:
        add(cmd[1], cmd[2], cmd[3]); print("added", cmd[1])
    elif cmd[:1] == ["use"]:
        use(cmd[1], cmd[2]); print("logged use of", cmd[1])
    elif cmd[:1] == ["reorder"]:
        for n, amt in reorder_list():
            print(f"order {amt:g} x {n}")
    else:
        print("usage: prep.py add NAME QTY PAR | use NAME QTY | reorder")
EOF
